  'Introduction to Graphic Design is a foundation course in visual communication, design process, typography, image, color, composition, systems, digital tools, critique, accessibility, and professional practice. Students learn to translate problems into purposeful visual form across print, screen, identity, information, and portfolio contexts.',
  $igdjjson${"slug": "introduction-to-graphic-design", "title": "Introduction to Graphic Design", "description": "Introduction to Graphic Design is a foundation course in visual communication, design process, typography, image, color, composition, systems, digital tools, critique, accessibility, and professional practice. Students learn to translate problems into purposeful visual form across print, screen, identity, information, and portfolio contexts.", "topics": [{"id": "0ead7abb-6553-40fa-b616-184d9af34d07", "type": "topic", "title": "What Graphic Design Is: Visual Communication, Context, and Audience", "description": "Students begin by seeing graphic design as purposeful communication, not decoration. The goal is to understand how designers shape meaning through form, context, audience, and constraints.", "children": [{"id": "1a24b080-078e-4f23-b7bd-5eb152f44d5c", "type": "subtopic", "title": "Design as communication", "children": [{"id": "4f435d2c-0d9a-49d6-ba0d-fba96b3467ec", "type": "concept", "title": "Sender, message, audience"}, {"id": "404dbfcd-781d-4c6e-973e-7a614958a694", "type": "concept", "title": "Visual rhetoric"}, {"id": "049e31ae-3b24-4fc5-9c07-1925794b941b", "type": "concept", "title": "Meaning and interpretation"}, {"id": "53e80754-de7d-46c8-924e-2690860df6c0", "type": "concept", "title": "Design constraints"}], "description": "This subtopic introduces design as a practice of making messages visible, usable, and persuasive."}, {"id": "2f5ec378-bf8b-46da-a7ee-25f155f66300", "type": "subtopic", "title": "Fields of practice", "children": [{"id": "264cedb1-ba34-48c6-92ce-f1e9f1d5aaef", "type": "concept", "title": "Brand identity"}, {"id": "90b2b74a-4ad5-499e-b91a-118efafd65db", "type": "concept", "title": "Editorial design"}, {"id": "9f3d57b6-4e07-4d86-b38a-08bc61fe2a59", "type": "concept", "title": "Information design"}, {"id": "50a7d4fb-bb33-47c9-b9e6-56b802420adc", "type": "concept", "title": "Digital products"}], "description": "Students map the breadth of the profession so early assignments connect to real design work."}, {"id": "968b28f5-2728-413d-a191-e4ca99150f7c", "type": "subtopic", "title": "Audience and context", "children": [{"id": "783187e9-fc9c-4793-a090-e80742de95b6", "type": "concept", "title": "Use context"}, {"id": "d6e3bd86-8af7-47d6-8bb4-a37977f833bf", "type": "concept", "title": "Cultural context"}, {"id": "fb5bf74f-b3ec-44f0-9412-86ad94213312", "type": "concept", "title": "Stakeholders"}, {"id": "22fe8ecd-4a0a-4eb8-82ba-33a1c8279da5", "type": "concept", "title": "Accessibility needs"}], "description": "Design choices become stronger when students ask who the work is for and where it will live."}]}, {"id": "f42b9aef-9267-4909-9f6b-cda042e40e41", "type": "topic", "title": "Design Process, Research, Briefs, and Problem Framing", "description": "World-class design education teaches process early: students learn to move from vague prompts to researched, testable design directions.", "children": [{"id": "23d07513-77db-40fe-9277-cb6672918e58", "type": "subtopic", "title": "Design briefs", "children": [{"id": "a25c14d7-8925-4f57-9916-cf5b80354dcb", "type": "concept", "title": "Problem statement"}, {"id": "32409186-ec5a-4db2-aade-011a58082521", "type": "concept", "title": "Objectives"}, {"id": "511bb291-f1fa-4be7-8e40-b40fc5d086f4", "type": "concept", "title": "Deliverables"}, {"id": "0406fbbd-4e7a-4fa7-a174-dfca4898115e", "type": "concept", "title": "Constraints"}], "description": "Students learn to read and write briefs that define purpose, audience, scope, deliverables, and success criteria."}, {"id": "1e36827c-d09c-4f5c-8adc-a09532475f01", "type": "subtopic", "title": "Research and precedent study", "children": [{"id": "24a5e8d1-8421-4785-8ae9-7db7180f7b24", "type": "concept", "title": "Visual audit"}, {"id": "1b76ef48-4311-4984-9717-ea96bcf9707c", "type": "concept", "title": "Competitor review"}, {"id": "c3d29dfa-4679-4921-b324-c00ff503f86f", "type": "concept", "title": "Mood boards"}, {"id": "e9188b0a-2673-4685-8e0d-380ebb3fb3ca", "type": "concept", "title": "Reference ethics"}], "description": "This subtopic builds the habit of looking outward before making form."}, {"id": "98337c68-78cf-4500-acb7-2bb464420e33", "type": "subtopic", "title": "Problem framing", "children": [{"id": "c5a7fe98-b39e-4645-a774-241950fbe8e1", "type": "concept", "title": "Reframing"}, {"id": "519b5ef0-ebde-4d54-b41f-d73381bd65a2", "type": "concept", "title": "How-might-we questions"}, {"id": "29513456-99c7-4946-b992-11f224a009d9", "type": "concept", "title": "Assumptions"}, {"id": "1ea08389-4e3c-4202-9f81-00715a456986", "type": "concept", "title": "Criteria for success"}], "description": "Students practice defining the right problem before solving it visually."}]}, {"id": "6bbd8d0b-2b58-449b-8fdc-8060220cb5cf", "type": "topic", "title": "Visual Elements: Point, Line, Shape, Form, Texture, and Space", "description": "Students develop a shared visual vocabulary for building compositions deliberately instead of relying on taste alone.", "children": [{"id": "5f196b60-2cc5-42f4-b198-f091a63e8d25", "type": "subtopic", "title": "Elements of form", "children": [{"id": "324a2b73-6834-4acd-bd4b-96126590a136", "type": "concept", "title": "Point"}, {"id": "5a03dd1a-5227-4e3f-bb1b-8636bf801cd3", "type": "concept", "title": "Line"}, {"id": "93691967-b6d6-411b-a1e1-47aab5474a27", "type": "concept", "title": "Plane"}, {"id": "cbaad412-ed38-4906-aba2-44ab653692a9", "type": "concept", "title": "Texture"}], "description": "This subtopic teaches the basic ingredients of visual language."}, {"id": "a4cfd8eb-5a60-4f11-8058-99bba8f252dd", "type": "subtopic", "title": "Positive and negative space", "children": [{"id": "11237025-e5db-46f9-854d-cd8937c85701", "type": "concept", "title": "Figure-ground"}, {"id": "b6cbc762-4a11-4d4d-b235-4f6c8a86f131", "type": "concept", "title": "Counterform"}, {"id": "644363a8-b0f2-433f-ba95-6eca32a1ead5", "type": "concept", "title": "Margins"}, {"id": "fe0cfc91-9773-4b35-b26c-77ad80d6ea15", "type": "concept", "title": "Whitespace"}], "description": "Students learn that what is left empty is as important as what is placed."}, {"id": "8f69b5d1-e6a1-4091-a1cb-fb6719076972", "type": "subtopic", "title": "Abstraction and simplification", "children": [{"id": "59904f77-eb26-4f2d-8f20-8ee0e4ba5ac1", "type": "concept", "title": "Iconic form"}, {"id": "6a9df15c-ce4f-4782-a710-a8f9d5df3671", "type": "concept", "title": "Silhouette"}, {"id": "21de80e0-fb4d-42fa-a9de-4239008c7b85", "type": "concept", "title": "Reduction"}, {"id": "6a9d5a04-8242-494b-b228-297f72913ea4", "type": "concept", "title": "Symbol making"}], "description": "Students practice reducing visual complexity while preserving meaning."}]}, {"id": "f01f6422-7196-4bab-a2f7-3d50ee23658c", "type": "topic", "title": "Composition Principles: Balance, Contrast, Rhythm, Unity, and Emphasis", "description": "Composition gives visual decisions structure. Students learn how to organize attention, movement, and relationships on a page or screen.", "children": [{"id": "621baed7-ac4f-40ad-b0a4-33742d2dded7", "type": "subtopic", "title": "Balance and tension", "children": [{"id": "038860b3-f62e-4942-b6f8-0ebf53b81a38", "type": "concept", "title": "Symmetry"}, {"id": "0ec001f0-5708-43b3-9ec1-1d5f98b3d898", "type": "concept", "title": "Asymmetry"}, {"id": "aa92a184-8b68-4eac-98df-cb5abf018046", "type": "concept", "title": "Weight"}, {"id": "5d76b7a0-913f-4cba-b291-ebcf04bb5afb", "type": "concept", "title": "Tension"}], "description": "Students compare symmetrical, asymmetrical, and dynamic balance as ways to create stability or energy."}, {"id": "3a9c23e8-00fa-46b2-ab5d-6bcbabfbc9ae", "type": "subtopic", "title": "Contrast and emphasis", "children": [{"id": "f2f20fc7-0caa-4d39-8ef9-49124fb0b504", "type": "concept", "title": "Scale contrast"}, {"id": "b9ebcb87-b081-402f-a956-497a7fc1e3da", "type": "concept", "title": "Value contrast"}, {"id": "560a9b50-a971-4d88-b106-51e4b11f7650", "type": "concept", "title": "Color contrast"}, {"id": "2c561e9e-0f66-49f4-9cdc-705699b4f157", "type": "concept", "title": "Typographic contrast"}], "description": "This subtopic shows how differences create hierarchy and meaning."}, {"id": "ac867ddf-0344-458d-a598-0c2eff000b9d", "type": "subtopic", "title": "Rhythm and unity", "children": [{"id": "58ebc0d1-6e08-4852-bcf0-365280fec6be", "type": "concept", "title": "Pattern"}, {"id": "a4d35f8b-025e-451a-b319-6143f4e50d94", "type": "concept", "title": "Repetition"}, {"id": "c8bd49ab-0d44-4d8d-80ad-9fe88cd3c16b", "type": "concept", "title": "Alignment"}, {"id": "cc1d597b-26cb-4629-a226-adf1a787e4df", "type": "concept", "title": "Visual rhythm"}], "description": "Students use repetition and variation to make work feel intentional."}]}, {"id": "289cff10-b91f-4ca1-8088-c731c6a1b00f", "type": "topic", "title": "Color Systems, Perception, Emotion, and Accessibility", "description": "Color is taught as perception, meaning, system, production issue, and accessibility responsibility.", "children": [{"id": "d2cc24e1-37a1-4894-827e-e2faaa3dc261", "type": "subtopic", "title": "Color models and production", "children": [{"id": "24222f61-be33-468c-a979-248373fe5606", "type": "concept", "title": "RGB"}, {"id": "1a18a0c3-e9ab-46e4-8c81-a427b442930f", "type": "concept", "title": "CMYK"}, {"id": "6e481aa1-c1c9-4470-a982-5aacbeace333", "type": "concept", "title": "Pantone"}, {"id": "dd55079e-e6a0-496a-b69e-c14796b76722", "type": "concept", "title": "Color profiles"}], "description": "Students distinguish screen, print, spot, and process color workflows."}, {"id": "c20a1e4b-ee46-4ceb-aa2f-5303f8265551", "type": "subtopic", "title": "Color relationships", "children": [{"id": "a5a16f3e-9475-424b-97bd-9d980b361bb1", "type": "concept", "title": "Complementary"}, {"id": "6ba31452-6de9-471d-8cea-16a938cb266c", "type": "concept", "title": "Analogous"}, {"id": "7ed3afa0-2aa9-4d81-aceb-2762e8ac2f41", "type": "concept", "title": "Triadic"}, {"id": "247a34d3-01f7-4cfb-b482-5747ca42b089", "type": "concept", "title": "Monochrome"}], "description": "This subtopic gives students usable palette strategies."}, {"id": "30a703ab-2763-44a6-b014-4492e417f209", "type": "subtopic", "title": "Color accessibility", "children": [{"id": "563798b8-b042-4f2c-9b16-10b4694d1d04", "type": "concept", "title": "WCAG contrast"}, {"id": "a96fa268-f80a-4e09-8cf0-17c814f5ab22", "type": "concept", "title": "Color blindness"}, {"id": "fb6a6016-73de-4b40-aa02-67cf1cb5f5cc", "type": "concept", "title": "Semantic color"}, {"id": "1adc2e8b-8092-450a-af1a-8df800d677bf", "type": "concept", "title": "Accessible palettes"}], "description": "Students learn to check contrast and avoid relying on color alone."}]}, {"id": "035eba2c-0102-4e19-b621-a540413d70f6", "type": "topic", "title": "Typography Foundations: Letterforms, Type Families, and Readability", "description": "Typography gives graphic design its voice. Students learn to choose, combine, and set type with care.", "children": [{"id": "2139a817-3c05-4138-a9e5-3e539a2de0d3", "type": "subtopic", "title": "Anatomy and classification", "children": [{"id": "558330f5-fc22-4740-877e-52512b64bf41", "type": "concept", "title": "Serif and sans serif"}, {"id": "39181c76-8905-4acb-bccb-9959041a6bb8", "type": "concept", "title": "X-height"}, {"id": "fc8d4948-b4d0-419f-8a85-b8c994537a65", "type": "concept", "title": "Weight"}, {"id": "1823a117-301a-499e-9cb9-2176b3f67e61", "type": "concept", "title": "Width"}], "description": "Students learn the vocabulary needed to evaluate letterforms and typefaces."}, {"id": "e54b6d86-fb53-4808-a4b7-ccf71dc7eb66", "type": "subtopic", "title": "Spacing and readability", "children": [{"id": "cd9511cb-921d-47f6-ad14-1c5c13560b4f", "type": "concept", "title": "Kerning"}, {"id": "032ad43d-d4e0-4377-86d7-bdbd1194ee86", "type": "concept", "title": "Tracking"}, {"id": "ea26e37f-a9d5-4fdc-8075-d1afb93d3f8c", "type": "concept", "title": "Leading"}, {"id": "eb61e73c-a49f-4f32-a396-bb77923e670d", "type": "concept", "title": "Line length"}], "description": "This subtopic focuses on micro-decisions that make text readable and professional."}, {"id": "bcfd1b12-e24e-4bed-bdaa-41302837284f", "type": "subtopic", "title": "Typographic voice", "children": [{"id": "7ab10cb3-5ad5-4930-90fe-bff4d17b5278", "type": "concept", "title": "Personality"}, {"id": "ec8f534f-cf23-45a5-9ecb-6a4672b53527", "type": "concept", "title": "Historical associations"}, {"id": "540ad311-809c-42b7-b74a-0ba9be7ab793", "type": "concept", "title": "Pairing"}, {"id": "2e95de91-3e39-4bf8-966d-2ed3ff5d2dee", "type": "concept", "title": "Mood"}], "description": "Students connect type choice to tone, audience, and message."}]}, {"id": "1c89e157-210a-4679-a49c-7cb104168ca2", "type": "topic", "title": "Hierarchy, Grids, Layout, and Editorial Systems", "description": "Students learn how designers organize complex information so readers know where to begin, continue, and act.", "children": [{"id": "4b9263d9-b450-4712-888c-64dd65fd0678", "type": "subtopic", "title": "Visual hierarchy", "children": [{"id": "02a10d0c-ca2a-423b-afb8-581236f2d4e2", "type": "concept", "title": "Primary/secondary/tertiary levels"}, {"id": "b8ba487e-4fe4-47c3-a6ed-42e4a8e583af", "type": "concept", "title": "Scale"}, {"id": "89042f44-574c-4cd2-96ec-7ff031282ad8", "type": "concept", "title": "Weight"}, {"id": "9a28919e-434d-4981-b65c-2f6045797bd9", "type": "concept", "title": "Contrast"}], "description": "This subtopic turns type, scale, color, and space into reading order."}, {"id": "04f55b0c-3a1f-46e9-adaa-a5c27760b9be", "type": "subtopic", "title": "Grid systems", "children": [{"id": "c133432a-6bdd-4d57-a08e-1dfeea9f2a5a", "type": "concept", "title": "Columns"}, {"id": "989fd7e9-704a-4f5a-be8a-0497ad4d071f", "type": "concept", "title": "Modules"}, {"id": "c4410fd4-9911-458d-be99-0240d5bad23f", "type": "concept", "title": "Baseline grids"}, {"id": "dfabc9e5-5ea6-4413-8225-4afaac339919", "type": "concept", "title": "Breaking the grid"}], "description": "Students use grids as flexible structures rather than rigid cages."}, {"id": "fcbe3d12-b554-407b-b57d-73d4752759fa", "type": "subtopic", "title": "Editorial composition", "children": [{"id": "6a951fcc-b70e-4310-8001-443f3903486d", "type": "concept", "title": "Headlines"}, {"id": "4235aea5-e147-417b-9aff-9c8145b0ad9a", "type": "concept", "title": "Captions"}, {"id": "da3aeadd-6847-44be-bd50-76083f673b4c", "type": "concept", "title": "Pull quotes"}, {"id": "00d5a2c2-30a2-4876-b034-8ce0d4c332d8", "type": "concept", "title": "Pagination"}], "description": "Students apply hierarchy and grids to spreads, posters, and multipage work."}]}, {"id": "a1efcce7-6e2c-4e0c-988e-e9ce8fd9d452", "type": "topic", "title": "Type and Image Relationships, Visual Storytelling, and Meaning", "description": "Graphic design often works through the tension between word and image. Students learn to combine them intentionally.", "children": [{"id": "8aec5f88-ae75-48fb-ae2f-bbc71d23ff29", "type": "subtopic", "title": "Image selection and cropping", "children": [{"id": "c3df50bc-2a94-4e05-bd16-29d34a67c307", "type": "concept", "title": "Cropping"}, {"id": "b9a81f23-03ca-47c6-8217-72ba4fc632a7", "type": "concept", "title": "Scale"}, {"id": "56c19817-28ac-454c-a8b5-45e849391b5f", "type": "concept", "title": "Point of view"}, {"id": "49d62a06-f29b-4c4c-b9b7-4107fe558040", "type": "concept", "title": "Image ethics"}], "description": "Students learn how image choice changes message, emotion, and credibility."}, {"id": "3646f423-311a-40b2-affb-f5df87d93faa", "type": "subtopic", "title": "Type-image integration", "children": [{"id": "d7a5ff04-7a01-4522-8f8f-3076675da9bd", "type": "concept", "title": "Overlay"}, {"id": "4b7a06fe-f2b0-494e-a110-f393a5fdb20e", "type": "concept", "title": "Juxtaposition"}, {"id": "89da055a-bcd2-4d84-87d1-9ebe073ee074", "type": "concept", "title": "Captioning"}, {"id": "da889c6e-9437-4181-a8af-9b7b8937023c", "type": "concept", "title": "Visual anchors"}], "description": "This subtopic teaches students to make type and image cooperate rather than compete."}, {"id": "deb7568c-2234-4b65-9539-0e67c5d03a3e", "type": "subtopic", "title": "Narrative sequence", "children": [{"id": "608f82b6-8ff5-4e6e-a307-53954dbc20c8", "type": "concept", "title": "Before/after"}, {"id": "d9bb583d-5bd5-40c5-b92f-34f8c75e18b3", "type": "concept", "title": "Story arc"}, {"id": "507c1aea-c19a-45df-94d4-487f39c7f431", "type": "concept", "title": "Series design"}, {"id": "1ab954d4-220f-4cba-97d0-84da46def8d5", "type": "concept", "title": "Pacing"}], "description": "Students practice designing meaning across a sequence, not just one frame."}]}, {"id": "ba6595b3-84d9-4ab8-afa4-ce4e1bea6b60", "type": "topic", "title": "Digital Tools and Production: Illustrator, Photoshop, InDesign, and Figma", "description": "Tools are introduced as production languages for design decisions, not as substitutes for thinking.", "children": [{"id": "926c8eb6-b71f-4094-9c41-49e59ed1b721", "type": "subtopic", "title": "Vector and raster workflows", "children": [{"id": "aa8b39a3-1f0e-441a-872b-7f387f81ec0d", "type": "concept", "title": "Illustrator"}, {"id": "20e8f165-f62b-4493-a3af-62de7880c38c", "type": "concept", "title": "Photoshop"}, {"id": "5724f18b-ab9d-4265-bc81-68f43d25a21f", "type": "concept", "title": "Resolution"}, {"id": "4eb881a0-4a79-4304-9659-9dbe4e078b08", "type": "concept", "title": "Export formats"}], "description": "Students learn when to use paths, pixels, layers, and masks."}, {"id": "07290885-860f-4ac8-990c-0a4b8a882569", "type": "subtopic", "title": "Page and screen tools", "children": [{"id": "67080cb5-cf45-4941-ac71-a1092f39a04a", "type": "concept", "title": "InDesign"}, {"id": "5f7820a6-5a5a-4c4b-8b12-4a97e2a3ffd7", "type": "concept", "title": "Figma"}, {"id": "f63be70e-4e94-410b-adb1-a8f35295d7ce", "type": "concept", "title": "Components"}, {"id": "d416289c-84db-418a-8eb8-7052e485438d", "type": "concept", "title": "Templates"}],