y."}, {"id": "322089a8-c6a7-473b-84e0-d82816d16307", "type": "subtopic", "title": "Design careers", "children": [{"id": "e47e5ba0-e5ce-436c-adde-ae8e25da6e95", "type": "concept", "title": "Studios"}, {"id": "fedacddf-7498-42dc-974e-45a569be71fc", "type": "concept", "title": "In-house teams"}, {"id": "5935d145-1cce-4b6e-8d2a-e9b3f39b75d2", "type": "concept", "title": "Freelance"}, {"id": "23f066e3-b21e-449b-b639-422ac81aba14", "type": "concept", "title": "Graduate study"}], "description": "Students map possible paths and next learning steps."}]}], "dbBacked": true}$igdjjson$::jsonb,
