values
  ('0ead7abb-6553-40fa-b616-184d9af34d07', 'f4a5b6c7-8d9e-4f82-9b12-2c3d4e5f6a92', null, 'topic'::public.curated_course_node_type, 'What Graphic Design Is: Visual Communication, Context, and Audience', 'Students begin by seeing graphic design as purposeful communication, not decoration. The goal is to understand how designers shape meaning through form, context, audience, and constraints.', 0),
